# Count rendered words, excluding duplicate plain-text/LaTeX representations.
def paragraph_words(p):
    if isinstance(p, str):
        return len(p.split())
    if "equation" in p:
        return len(p["equation"].split())
    t = p["table"]
    return sum(len(str(x).split()) for x in [t["caption"], t["note"], *t["headers"], *[cell for row in t["rows"] for cell in row]])

paper["word_count"] = len(paper["title"].split()) + len(paper["abstract"].split()) + sum(len(x["heading"].split())+sum(paragraph_words(p) for p in x["paragraphs"]) for x in paper["sections"]) + sum(len(x["text"].split()) for x in paper["references"]) + sum(len(x["heading"].split())+sum(paragraph_words(p) for p in x["paragraphs"]) for x in paper["declarations"])
assert 150 <= len(paper["abstract"].split()) <= 250
assert 6000 <= paper["word_count"] <= 8000, paper["word_count"]
assert len(paper["references"]) == 20
